SELECT P.*, D.* 
FROM PROFESSOR P
LEFT JOIN DEPARTMENT D ON P.DEPTNO = D.DEPTNO 
WHERE P.NAME LIKE concat('%', #{keyword} , '%')

	AND P.DEPTNO = #{deptNo}


	AND P.POSITION = #{position}

